#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_WORDS 100
#define MAX_LEN 20

int main() {
    int n;
    char words[MAX_WORDS][MAX_LEN + 1];

    // Read number of words
    if (scanf("%d", &n) != 1) return 1;

    // Read all words
    for (int i = 0; i < n; i++) {
        if (scanf("%s", words[i]) != 1) return 1;
    }

    // Check if sorted
    for (int i = 0; i < n - 1; i++) {
        char *a = words[i];
        char *b = words[i + 1];

        int cmp = strcmp(a, b);
        if (cmp > 0) {
            printf("false\n");
            return 0;
        } else if (cmp == 0) {
            // Equal words are fine, but if a is longer than b, it's not a prefix
            // Actually equal words are trivially sorted
            continue;
        } else {
            // a < b: check if a is a prefix of b
            int len_a = strlen(a);
            int len_b = strlen(b);
            if (len_a > len_b) {
                // a longer than b but a < b lexicographically means not sorted
                // because prefix rule: if a is longer than b, a cannot be prefix of b
                // and lexicographic order says shorter word comes first if it's a prefix
                // Example: "ba" vs "b" -> "ba" > "b" lexicographically, but should be false
                // Actually we need to check: if a is not a prefix and a < b, it's fine
                // But if a is longer than b and a < b, that's impossible because
                // if a is longer than b and a starts with b, then a > b (since extra chars)
                // If a doesn't start with b, then normal lexicographic applies
                // So we only need to check the case where a starts with b and a is longer
                if (strncmp(a, b, len_b) == 0) {
                    printf("false\n");
                    return 0;
                }
            }
        }
    }

    printf("true\n");
    return 0;
}

