int rank[256];

int compare(const char *a, const char *b) {
    int i = 0;
    while (a[i] && b[i]) {
        if (rank[(unsigned char)a[i]] < rank[(unsigned char)b[i]]) return -1;
        if (rank[(unsigned char)a[i]] > rank[(unsigned char)b[i]]) return 1;
        i++;
    }
    if (a[i] == '\0' && b[i] == '\0') return 0;
    if (a[i] == '\0') return -1; // a is prefix of b, a comes first
    return 1; // b is prefix of a, b comes first (a > b)
}

