int pos[256];

int cmp_words(const char *a, const char *b) {
    int i = 0;
    while (a[i] && b[i]) {
        if (a[i] != b[i]) {
            return pos[(unsigned char)a[i]] - pos[(unsigned char)b[i]];
        }
        i++;
    }
    if (!a[i] && !b[i]) return 0;
    if (!a[i]) return -1;   // a is prefix of b
    return 1;               // b is prefix of a
}

