        for (int j = 0; j < min(a.size(), b.size()); j++) {
            if (rank[a[j]-'a'] < rank[b[j]-'a']) { ok = true; found = true; break; }
            if (rank[a[j]-'a'] > rank[b[j]-'a']) { ok = false; found = true; break; }
        }
        if (!found) {
            // one is prefix of another
