int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> words(n);
    for (int i = 0; i < n; ++i) cin >> words[i];

    vector<vector<int>> g(26);
    vector<int> indeg(26, 0);
    bool ok = true;

    for (int i = 0; i + 1 < n; ++i) {
        const string &a = words[i];
        const string &b = words[i + 1];

        int len = min(a.size(), b.size());
        int j = 0;
        while (j < len && a[j] == b[j]) ++j;

        if (j == len) {
            if (a.size() > b.size()) {
                ok = false; // longer word before its prefix
                break;
            }
        } else {
            int u = a[j] - 'a';
            int v = b[j] - 'a';
            if (u != v) {
                bool exists = false;
                for (int to : g[u]) {
                    if (to == v) {
                        exists = true;
                        break;
                    }
                }
                if (!exists) {
                    g[u].push_back(v);
                    indeg[v]++;
                }
            }
        }
    }

    if (!ok) {
        cout << "Impossible\n";
        return 0;
    }

    queue<int> q;
    for (int i = 0; i < 26; ++i) {
        if (indeg[i] == 0) q.push(i);
    }

    string order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(char('a' + u));
        for (int v : g[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }

    if ((int)order.size() != 26) {
        cout << "Impossible\n";
    } else {
        cout << order << '\n';
    }

    return 0;
}

