public class LexicographicalOrder {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String[] words = new String[n];
        for (int i = 0; i < n; i++) {
            words[i] = br.readLine().trim();
        }

        // Build the order map from the first word
        String first = words[0];
        Map<Character, Integer> order = new HashMap<>();
        for (int i = 0; i < first.length(); i++) {
            char c = first.charAt(i);
            if (!order.containsKey(c)) {
                order.put(c, order.size());
            }
        }

        // Determine the order from all words
        for (int i = 0; i < n - 1; i++) {
            String a = words[i];
            String b = words[i + 1];
            int minLen = Math.min(a.length(), b.length());
            boolean foundDifference = false;
            for (int j = 0; j < minLen; j++) {
                char ca = a.charAt(j);
                char cb = b.charAt(j);
                if (ca != cb) {
                    if (!order.containsKey(ca)) {
                        order.put(ca, order.size());
                    }
                    if (!order.containsKey(cb)) {
                        order.put(cb, order.size());
                    }
                    if (order.get(ca) > order.get(cb)) {
                        System.out.println("false");
                        return;
                    }
                    foundDifference = true;
                    break;
                }
            }
            if (!foundDifference && a.length() > b.length()) {
                // Prefix case: longer word should come after shorter
                System.out.println("false");
                return;
            }
        }

        System.out.println("true");
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String alphabet = sc.nextLine().trim();

        // Build rank map
        int[] rank = new int[26];
        for (int i = 0; i < alphabet.length(); i++) {
            rank[alphabet.charAt(i) - 'a'] = i;
        }

        int n = Integer.parseInt(sc.nextLine().trim());
        String[] words = new String[n];
        for (int i = 0; i < n; i++) {
            words[i] = sc.nextLine().trim();
        }

        boolean sorted = true;
        for (int i = 0; i < n - 1; i++) {
            if (!isOrdered(words[i], words[i+1], rank)) {
                sorted = false;
                break;
            }
        }

        System.out.println(sorted ? "YES" : "NO");
    }

    static boolean isOrdered(String a, String b, int[] rank) {
        int len = Math.min(a.length(), b.length());
        for (int i = 0; i < len; i++) {
            int ra = rank[a.charAt(i) - 'a'];
            int rb = rank[b.charAt(i) - 'a'];
            if (ra < rb) return true;
            if (ra > rb) return false;
        }
        // a is prefix of b: a <= b (a precedes b, which is valid)
        // b is prefix of a: b < a (invalid, b should come after a)
        return a.length() <= b.length();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        if (!fs.hasNext()) return;
        n = fs.nextInt();

        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = fs.next();

        // Graph of letter precedence constraints: u -> v means u must come before v
        boolean[][] g = new boolean[26][26];

        for (int i = 0; i + 1 < n; i++) {
            String a = words[i];
            String b = words[i + 1];

            int len = Math.min(a.length(), b.length());
            int j = 0;
            while (j < len && a.charAt(j) == b.charAt(j)) j++;

            if (j == len) {
                // One is prefix of the other. Valid only if shorter comes first.
                if (a.length() > b.length()) {
                    System.out.println("no");
                    return;
                }
            } else {
                int u = a.charAt(j) - 'a';
                int v = b.charAt(j) - 'a';
                if (u != v) g[u][v] = true;
            }
        }

        // Check if precedence graph has a cycle.
        int[] state = new int[26]; // 0=unvisited, 1=visiting, 2=done
        for (int i = 0; i < 26; i++) {
            if (state[i] == 0 && hasCycle(i, g, state)) {
                System.out.println("no");
                return;
            }
        }

        System.out.println("yes");
    }

    static boolean hasCycle(int u, boolean[][] g, int[] state) {
        state[u] = 1;
        for (int v = 0; v < 26; v++) {
            if (!g[u][v]) continue;
            if (state[v] == 1) return true;
            if (state[v] == 0 && hasCycle(v, g, state)) return true;
        }
        state[u] = 2;
        return false;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        boolean hasNext() throws IOException {
            int c;
            while ((c = read()) != -1) {
                if (!Character.isWhitespace(c)) {
                    ptr--;
                    return true;
                }
            }
            return false;
        }

        String next() throws IOException {
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c)) {}
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (c != -1 && !Character.isWhitespace(c));
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

